  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Kežmarský hrad', 'Městský hrad ze 15. století přímo v centru svobodného královského města Kežmarok. Kousek od něj stojí dřevěný artikulární kostel zapsaný na seznamu UNESCO – celý z tisového a smrkového dřeva, bez jediného hřebíku. Ideální start okruhu s kávou na historickém náměstí.', 49.1394, 20.4319, 'https://commons.wikimedia.org/wiki/Special:FilePath/Kezmarok%20Castle.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Kezmarok%20Castle.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Kezmarok%20hrad.jpg"}'::text[], 0),
    (v_route, 'Ždiar', 'Goralská obec pod Belianskými Tatrami proslulá malovanými roubenkami a živým folklórem. Silnice přes Ždiar patří k nejhezčím podtatranským úsekům – po pravé ruce se zvedá vápencová hradba Belianských Tater. Zastavte u vyhlídky nad obcí na jednu z nejfotografovanějších tatranských scenérií.', 49.2717, 20.2661, 'https://commons.wikimedia.org/wiki/Special:FilePath/Zdiar.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Zdiar.jpg"}'::text[], 1),
    (v_route, 'Osturňa', 'Nejzápadnější rusínská obec Slovenska a památková rezervace – sedm kilometrů dlouhá řada srubových usedlostí podél potoka. Úzká slepá silnička sem vede zvlněnou krajinou Spišské Magury a je zážitkem sama o sobě. Jeďte pomalu, potkáte tu více ovcí než aut.', 49.3369, 20.2264, 'https://commons.wikimedia.org/wiki/Special:FilePath/Osturna.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Osturna.jpg"}'::text[], 2),
    (v_route, 'Červený Kláštor', 'Kartuziánský klášter ze 14. století na břehu Dunajce, spjatý s legendárním létajícím mnichem Cypriánem. Dnes je tu muzeum, bylinková zahrada a hlavní přístaviště tradičních plťí. Odsud vyplouvají vory do soutěsky – plavba trvá zhruba hodinu a půl a motorku můžete nechat na hlídaném parkovišti.', 49.3946, 20.4224, 'https://commons.wikimedia.org/wiki/Special:FilePath/%C4%8Cerven%C3%BD%20Kl%C3%A1%C5%A1tor.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/%C4%8Cerven%C3%BD%20Kl%C3%A1%C5%A1tor.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Cerveny%20Klastor.jpg"}'::text[], 3),
    (v_route, 'Prielom Dunajca – plte', 'Devítikilometrový vápencový kaňon Dunajce mezi slovenskými a polskými Pieninami, nad nímž se tyčí trojzubý masiv Tri koruny. Řeka tu tvoří sedm ostrých meandrů sevřených tři sta metrů vysokými stěnami. Krátká zastávka na vyhlídce u silnice stojí za to i bez plavby na voru.', 49.3983, 20.4670, 'https://commons.wikimedia.org/wiki/Special:FilePath/Prielom%20Dunajca.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Prielom%20Dunajca.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Pieniny%20Dunajec.jpg"}'::text[], 4),
    (v_route, 'Hrad Stará Ľubovňa', 'Mohutný pohraniční hrad nad údolím Popradu, kde byly za polského záboru ukrývány polské korunovační klenoty. Pod hradem leží skanzen s dřevěným řeckokatolickým kostelíkem a spišskými chalupami. Z hradeb je krásný výhled na Tatry i celé Zamagurie.', 49.3164, 20.6959, 'https://commons.wikimedia.org/wiki/Special:FilePath/Lubovniansky%20hrad.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Lubovniansky%20hrad.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Hrad%20Stara%20Lubovna.jpg"}'::text[], 5),
    (v_route, 'Restaurace: Hotel Hviezdoslav (Kežmarok)', 'Restaurace butikového hotelu v historickém domě přímo na hlavní ulici Kežmarku, pojmenovaného po básníku Hviezdoslavovi. Kuchyně kombinuje moderní gastronomii se spišskou klasikou – pirohy, jehněčí i tatranský pstruh. Hosté ji dlouhodobě řadí k nejlepším podnikům pod Tatrami, ideální tečka za okruhem.', 49.1352, 20.4276, 'https://commons.wikimedia.org/wiki/Special:FilePath/Kezmarok.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Kezmarok.jpg"}'::text[], 6);
