  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Prešov – Hlavná ulica', 'Metropole Šariše s vřetenovitým historickým náměstím, gotickou konkatedrálou svatého Mikuláše a řadou renesančních měšťanských domů. Před startem stojí za to projít si korzo a dát si kávu pod arkádami. Město je zároveň nejpohodlnějším místem na dotankování před okruhem.', 48.9977, 21.2401, 'https://commons.wikimedia.org/wiki/Special:FilePath/Pre%C5%A1ov%20-%20Hlavn%C3%A1%20ulica.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Pre%C5%A1ov%20-%20Hlavn%C3%A1%20ulica.jpg"}'::text[], 0),
    (v_route, 'Šarišský hrad', 'Jedna z nejrozsáhlejších hradních zřícenin na Slovensku na výrazném sopečném kopci nad Veľkým Šarišem. Z parkoviště pod kopcem vede nahoru půlhodinová procházka odměněná kruhovým výhledem na celé údolí Torysy. Hrad býval správním centrem celé šarišské župy.', 49.0428, 21.2103, 'https://commons.wikimedia.org/wiki/Special:FilePath/Sarissky%20hrad.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Sarissky%20hrad.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/%C5%A0ari%C5%A1sk%C3%BD%20hrad.jpg"}'::text[], 1),
    (v_route, 'Bardejov – Radničné námestie (UNESCO)', 'Nejzachovalejší středověké město Slovenska, zapsané na seznamu UNESCO. Náměstí lemují gotické měšťanské domy, uprostřed stojí renesanční radnice a bazilika svatého Egídia ukrývá jedenáct původních gotických křídlových oltářů. Motorku zaparkujete hned za hradbami.', 49.2937, 21.2765, 'https://commons.wikimedia.org/wiki/Special:FilePath/Bardejov%20-%20Radni%C4%8Dn%C3%A9%20n%C3%A1mestie.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Bardejov%20-%20Radni%C4%8Dn%C3%A9%20n%C3%A1mestie.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Bardejov%20radnica.jpg"}'::text[], 2),
    (v_route, 'Bardejovské kúpele', 'Klidné lázně v lesích nad Bardejovem, kam jezdila císařovna Sisi i ruský car Alexandr I. Kolonádu doplňuje nejstarší skanzen na Slovensku s dřevěnými kostelíky a šarišskými chalupami. Příjemná zastávka na minerálku přímo z pramene.', 49.3220, 21.2650, 'https://commons.wikimedia.org/wiki/Special:FilePath/Bardejovske%20kupele.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Bardejovske%20kupele.jpg"}'::text[], 3),
    (v_route, 'Dřevěný kostelík Hervartov (UNESCO)', 'Nejstarší dřevěný kostel na Slovensku z konce 15. století, celý z červeného smrku a zapsaný na seznamu UNESCO. Uvnitř se dochovaly gotické nástěnné malby a original oltář. Kostelík stojí uprostřed vesničky pod lesy Čergova – klíč půjčuje místní správce.', 49.2453, 21.2166, 'https://commons.wikimedia.org/wiki/Special:FilePath/Hervartov%20church.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Hervartov%20church.jpg"}'::text[], 4),
    (v_route, 'Restaurace: Roland (Bardejov)', 'Oblíbená restaurace přímo na bardejovském náměstí s letní terasou pod gotickými štíty. Vaří poctivou šarišskou i mezinárodní kuchyni – vyhlášené jsou pirohy s bryndzou a kachní stehno. Výborné hodnocení hostů a rychlá obsluha z ní dělají ideální zastávku na oběd v polovině okruhu.', 49.2934, 21.2760, 'https://commons.wikimedia.org/wiki/Special:FilePath/Bardejov%20radnica.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Bardejov%20radnica.jpg"}'::text[], 5);
  insert into public.routes
