  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Kaštieľ Humenné', 'Renesanční zámek rodu Drugethů uprostřed parku v centru Humenného, dnes vlastivědné muzeum s expozicí šlechtického bydlení. Za zámkem leží skanzen s dřevěným kostelíkem a rusínskými chalupami z okolních Karpat. Dobré místo na první kávu před cestou na východ.', 48.9328, 21.9105, 'https://commons.wikimedia.org/wiki/Special:FilePath/Kastiel%20Humenne.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Kastiel%20Humenne.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Humenne%20kastiel.jpg"}'::text[], 0),
    (v_route, 'Zemplínska šírava', 'Druhá největší vodní plocha Slovenska, přezdívaná východoslovenské moře. Jižní břeh lemují pláže a přístaviště, severní obepíná sopečné pohoří Vihorlat. Silnice podél severního břehu nabízí příjemné zatáčky s výhledy na hladinu – ideální krátká zastávka u vody.', 48.7942, 22.0500, 'https://commons.wikimedia.org/wiki/Special:FilePath/Zemplinska%20sirava.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Zemplinska%20sirava.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Zempl%C3%ADnska%20%C5%A1%C3%ADrava.jpg"}'::text[], 1),
    (v_route, 'Morské oko (Vihorlat)', 'Smaragdové jezero sopečného původu ukryté v bukových pralesích Vihorlatu, součást světového dědictví UNESCO. Lesní silnička z Remetských Hámrů končí na parkovišti, odkud je to k hladině pár minut pěšky. Nad jezerem se zvedá skalnatý Sninský kameň s jedním z nejkrásnějších výhledů východu.', 48.9126, 22.2833, 'https://commons.wikimedia.org/wiki/Special:FilePath/Morske%20oko.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Morske%20oko.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Vihorlat%20Morske%20oko.jpg"}'::text[], 2),
    (v_route, 'Restaurace: Kaštieľ Snina (Snina)', 'Citlivě zrekonstruovaný klasicistní zámeček rodiny Rholl v centru Sniny s vyhlášenou restaurací a kavárnou na nádvoří. Kuchyně staví na regionálních surovinách a rusínských receptech v moderním podání. Poslední pořádné jídlo a tankování před vjezdem do liduprázdných Polonin.', 48.9884, 22.1569, 'https://commons.wikimedia.org/wiki/Special:FilePath/Kastiel%20Snina.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Kastiel%20Snina.jpg"}'::text[], 3),
    (v_route, 'Hvezdáreň Kolonica – Park tmavé oblohy', 'Astronomická observatoř na Kolonickém sedle uprostřed Parku tmavé oblohy Poloniny – oblasti s nejtmavší noční oblohou ve střední Evropě. Přes den si prohlédnete největší dalekohled na Slovensku, za jasných nocí se tu konají veřejná pozorování. Ze sedla se otevírá výhled na hřebeny Bukovských vrchů.', 48.9353, 22.2764, 'https://commons.wikimedia.org/wiki/Special:FilePath/Kolonica%20Observatory.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Kolonica%20Observatory.jpg"}'::text[], 4),
    (v_route, 'Dřevěný kostelík Topoľa', 'Řeckokatolická dřevěná cerkev svatého archanděla Michala ze 17. století na kopečku nad vesničkou Topoľa. Patří k pokladům rusínské sakrální architektury Polonin – celá roubená, s šindelovou střechou a třemi věžičkami. U kostelíka je malý hřbitov s kamennými kříži.', 49.0322, 22.3378, 'https://commons.wikimedia.org/wiki/Special:FilePath/Topo%C4%BEa%20-%20dreven%C3%BD%20kostol%C3%ADk.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Topo%C4%BEa%20-%20dreven%C3%BD%20kostol%C3%ADk.jpg"}'::text[], 5),
    (v_route, 'Nová Sedlica – nejvýchodnější obec', 'Nejvýchodnější obec Slovenska na konci silnice pod Kremencem, kde se stýkají hranice Slovenska, Polska a Ukrajiny. Symbolické místo pro dojezdovou fotku – dál už vede jen turistický chodník do pralesů Polonin. V obci je malý skanzen a bufet, odkud se vydávají turisté na trojmezí.', 49.0511, 22.5153, 'https://commons.wikimedia.org/wiki/Special:FilePath/Nova%20Sedlica.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Nova%20Sedlica.jpg"}'::text[], 6);
  insert into public.routes
    (id, branch_id, name, description, route_type, distance_km, duration_min, difficulty,
  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Herliansky gejzír', 'Jediný studený gejzír ve střední Evropě, který v pravidelných intervalech zhruba 32 až 36 hodin tryská až patnáct metrů vysoko. Vznikl nechtěně při vrtu v 19. století a chrlí vodu už přes sto čtyřicet let. Časy erupcí zveřejňuje obec – pokud vyjde termín, je to nezapomenutelná podívaná.', 48.8014, 21.4767, 'https://commons.wikimedia.org/wiki/Special:FilePath/Herliansky%20gejzir.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Herliansky%20gejzir.jpg"}'::text[], 0),
    (v_route, 'Hrad Slanec', 'Zřícenina gotického hradu na strmém sopečném kuželu nad stejnojmennou obcí, s obnovenou věží a vyhlídkovou plošinou. Střežil obchodní stezku z Košické kotliny na Zemplín – dnes z věže dohlédnete od Slanských vrchů až k maďarské rovině. Výstup od parkoviště trvá asi dvacet minut.', 48.6353, 21.4750, 'https://commons.wikimedia.org/wiki/Special:FilePath/Slanec%20hrad.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Slanec%20hrad.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Hrad%20Slanec.jpg"}'::text[], 1),
    (v_route, 'Rozhledna Tokaj (Veľká Tŕňa)', 'Dřevěná rozhledna ve tvaru vinného soudku uprostřed vinic nad Veľkou Tŕňou, symbol slovenského Tokaje. Z ochozu ve výšce dvanácti metrů přehlédnete celou tokajskou oblast až k maďarskému Tokaji a řece Bodrog. Kolem vede vinařská cyklostezka a mezi vinicemi se krásně fotí.', 48.4550, 21.6850, 'https://commons.wikimedia.org/wiki/Special:FilePath/Rozh%C4%BEad%C5%88a%20Tokaj.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Rozh%C4%BEad%C5%88a%20Tokaj.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Velka%20Trna.jpg"}'::text[], 2),
    (v_route, 'Restaurace: Tokaj Macík Winery (Malá Tŕňa)', 'Rodinné vinařství s restaurací a stovky let starými tufovými sklepy v srdci slovenského Tokaje. Podávají zemplínské speciality laděné k místním vínům – husacinu, sýry i degustační menu; podnik patří k nejlépe hodnoceným v regionu. Řidičům nalijí hroznový mošt, láhev tokajského výběru si odvezete v kufru.', 48.4392, 21.6944, 'https://commons.wikimedia.org/wiki/Special:FilePath/Mala%20Trna.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Mala%20Trna.jpg"}'::text[], 3),
    (v_route, 'Kaštieľ Borša', 'Renesanční vodní kaštieľ v obci Borša u Bodrogu, rodiště sedmihradského knížete a vůdce protihabsburského povstání Františka II. Rákócziho. Po velkorysé rekonstrukci nabízí moderní expozici o rodu Rákócziů a příjemnou kavárnu v parku. Významné poutní místo maďarské historie pár kroků od hranice.', 48.3944, 21.7161, 'https://commons.wikimedia.org/wiki/Special:FilePath/Kastiel%20Borsa.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Kastiel%20Borsa.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Borsa%20kastiel.jpg"}'::text[], 4),
    (v_route, 'Kaštieľ Andrássyovců (Trebišov)', 'Klasicistní zámek hraběcího rodu Andrássyů v rozlehlém anglickém parku v centru Trebišova, dnes muzeum Zemplína s expozicí vinařství a tokajských sklepů. V parku najdete i mauzoleum rodu a zříceninu hradu Parič. Klidná zastávka ve stínu staletých platanů na zpáteční cestě.', 48.6280, 21.7190, 'https://commons.wikimedia.org/wiki/Special:FilePath/Kastiel%20Trebisov.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Kastiel%20Trebisov.jpg"}'::text[], 5);
  insert into public.routes
    (id, branch_id, name, description, route_type, distance_km, duration_min, difficulty,
  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Ochtinská aragonitová jaskyňa (UNESCO)', 'Jedna z pouhých tří zpřístupněných aragonitových jeskyní na světě, zapsaná na seznamu UNESCO. Místo klasických krápníků tu rostou sněhobílé trsy aragonitu připomínající korály a ledové květy. Prohlídka trvá půl hodiny a jeskyně má stálých sedm stupňů – bunda se hodí i v létě.', 48.6656, 20.3011, 'https://commons.wikimedia.org/wiki/Special:FilePath/Ochtinska%20aragonitova%20jaskyna.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Ochtinska%20aragonitova%20jaskyna.jpg"}'::text[], 0),
    (v_route, 'Revúca – První slovenské gymnázium', 'Městečko pod Muránskou planinou, kde bylo roku 1862 založeno první slovenské gymnázium – budova s klasicistním průčelím dnes slouží jako národní kulturní památka s muzeem. Revúca je přirozeným centrem horního Gemeru a dobrým místem na kávu před horskou částí trasy.', 48.6836, 20.1131, 'https://commons.wikimedia.org/wiki/Special:FilePath/Prve%20slovenske%20gymnazium%20Revuca.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Prve%20slovenske%20gymnazium%20Revuca.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Revuca.jpg"}'::text[], 1),
    (v_route, 'Muránský hrad', 'Zřícenina jednoho z nejvýše položených hradů Slovenska (935 m) na vápencovém ostrohu Cigánka nad obcí Muráň. Proslavila ho krásná hradní paní Mária Séči, přezdívaná Muránská Venuše. Od parkoviště pod Velkou lúkou vede nahoru hodinová stezka s výhledy na celou planinu.', 48.7592, 20.0281, 'https://commons.wikimedia.org/wiki/Special:FilePath/Muransky%20hrad.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Muransky%20hrad.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Muran%20hrad.jpg"}'::text[], 2),
    (v_route, 'Muránska planina – Veľká lúka', 'Rozlehlá horská louka v srdci národního parku Muránska planina, domov polodivokých koní plemene norik muránského typu. Krasová planina je protkaná závrty, roklemi a pralesy – z Velké lúky je nejhezčí pohled na hradní skálu. Silnice přes planinu je zážitkem i bez sesednutí z motorky.', 48.7597, 20.0731, 'https://commons.wikimedia.org/wiki/Special:FilePath/Muranska%20planina.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Muranska%20planina.jpg"}'::text[], 3),
    (v_route, 'Restaurace: Salaš Zbojská (sedlo Zbojská)', 'Legendární salaš přímo v sedle Zbojská na rozhraní Gemeru a Horehroní, oblíbená zastávka motorkářů z celého Slovenska. Vlastní ovčí farma zásobuje kuchyni – bryndzové halušky, žinčica, sýry a jehněčí patří k nejlepším v zemi. V ohradách se prohánějí ovce a koně, terasa voní údeným sýrem.', 48.7228, 19.8983, 'https://commons.wikimedia.org/wiki/Special:FilePath/Sedlo%20Zbojska.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Sedlo%20Zbojska.jpg"}'::text[], 4),
    (v_route, 'Tisovec – ozubnicová dráha', 'Horské městečko pod vápencovou Hradovou, kam vede z Pohronské Polhory unikátní ozubnicová železnice z roku 1896 – v letní sezóně po ní jezdí historické vlaky. Trať šplhá souběžně se silnicí přes sedlo Zbojská, takže s trochou štěstí pojedete chvíli závod s parní lokomotivou.', 48.6800, 19.9436, 'https://commons.wikimedia.org/wiki/Special:FilePath/Tisovec.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Tisovec.jpg"}'::text[], 5);
