    (id, branch_id, name, description, route_type, distance_km, duration_min, difficulty,
  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Múzeum slovenskej dediny (Martin)', 'Největší skanzen na Slovensku na okraji Martina – přes sto přenesených dřevěnic, kostelík, krčma i zvonice z celého Turce, Oravy a Kysuc. Procházka mezi chalupami zabere hodinku a krásně naladí na horskou část trasy. V areálu funguje dobová hospoda s regionálními jídly.', 49.0453, 18.9481, 'https://commons.wikimedia.org/wiki/Special:FilePath/M%C3%BAzeum%20slovenskej%20dediny.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/M%C3%BAzeum%20slovenskej%20dediny.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Muzeum%20slovenskej%20dediny.jpg"}'::text[], 0),
    (v_route, 'Gaderská dolina (Blatnica)', 'Skalní brána Veľké Fatry u obce Blatnica – dvanáct kilometrů dlouhá krasová dolina s bílými vápencovými věžemi a potokem plným pstruhů. Nad ústím doliny se zvedá zřícenina Blatnického hradu. Motorka zůstane na parkovišti u vstupu, i krátká procházka podél potoka ale stojí za zastávku.', 48.9333, 18.9556, 'https://commons.wikimedia.org/wiki/Special:FilePath/Gaderska%20dolina.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Gaderska%20dolina.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Blatnicky%20hrad.jpg"}'::text[], 1),
    (v_route, 'Harmanecká jaskyňa', 'Krápníková jeskyně vysoko ve stráni nad harmaneckými serpentinami, proslulá bílými pagodovými stalagmity a největší kolonií netopýrů na Slovensku. K vchodu vede od parkoviště u silnice strmý lesní chodník – počítejte se čtyřiceti minutami stoupání. Skvělá záminka protáhnout nohy uprostřed nejklikatější silnice země.', 48.8147, 19.0403, 'https://commons.wikimedia.org/wiki/Special:FilePath/Harmanecka%20jaskyna.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Harmanecka%20jaskyna.jpg"}'::text[], 2),
    (v_route, 'Kremnické Bane – střed Evropy', 'U kostelíka svatého Jana Křtitele nad hornickou obcí Kremnické Bane leží jeden z vypočtených geografických středů Evropy, označený žulovým monumentem. Ať už výpočtu věříte, nebo ne, výhled z návrší na Kremnické vrchy je krásný a fotka u středu kontinentu je povinná.', 48.7400, 18.9130, 'https://commons.wikimedia.org/wiki/Special:FilePath/Kremnicke%20Bane.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Kremnicke%20Bane.jpg"}'::text[], 3),
    (v_route, 'Kremnica – mincovna a městský hrad', 'Středověké zlatohorní město, kde se od roku 1328 nepřetržitě razí mince – kremnická mincovna je nejstarší fungující na světě a razila i české dukáty. Nad náměstím s morovým sloupem se zvedá opevněný městský hrad s kostelem svaté Kateřiny. Prohlídka mincovny s ražbou vlastní pamětní mince je originální suvenýr.', 48.7050, 18.9183, 'https://commons.wikimedia.org/wiki/Special:FilePath/Kremnica.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Kremnica.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Kremnica%20namestie.jpg"}'::text[], 4),
    (v_route, 'Turčianske Teplice', 'Lázeňské městečko s termální vodou o teplotě přes čtyřicet stupňů, kde se léčil už uherský král Zikmund. Dominantou je modrobílý secesní lázeňský dům Modrý kúpeľ. Příjemná krátká zastávka v parku před posledním rovinatým úsekem zpět do Martina.', 48.8631, 18.8611, 'https://commons.wikimedia.org/wiki/Special:FilePath/Turcianske%20Teplice.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Turcianske%20Teplice.jpg"}'::text[], 5),
    (v_route, 'Restaurace: Hotel Čierna pani (Martin)', 'Tradiční hotelová restaurace v centru Martina, pojmenovaná podle pověsti o černé paní z martinského zámečku. Vaří poctivou turčianskou a slovenskou kuchyni – halušky, pečenou kachnu i denní menu za férové ceny, dlouhodobě s výborným hodnocením. Ideální tečka za okruhem plným serpentin.', 49.0653, 18.9203, 'https://commons.wikimedia.org/wiki/Special:FilePath/Martin%20(Slovakia).jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Martin%20(Slovakia).jpg"}'::text[], 6);
  insert into public.routes
    (id, branch_id, name, description, route_type, distance_km, duration_min, difficulty,
  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Rajecké Teplice – lázně', 'Nejmenší slovenské lázeňské město s termálními prameny a elegantním lázeňským domem Aphrodite ve stylu antických lázní. Park s jezírkem přímo u kolonády je příjemným startem okruhu. Po náročnějším dni se sem vyplatí vrátit na večerní koupel v termální vodě.', 49.1264, 18.6828, 'https://commons.wikimedia.org/wiki/Special:FilePath/Rajecke%20Teplice.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Rajecke%20Teplice.jpg"}'::text[], 0),
    (v_route, 'Rajecká Lesná – Slovenský betlém', 'Poutní obec s bazilikou Narození Panny Marie a proslulým Slovenským betlémem – patnáct metrů dlouhým vyřezávaným dílem mistra Pekary, kde se stovky figurek pohybují mezi miniaturami slovenských památek. Vstup je zdarma a betlém funguje po celý rok. Jedno z nejnavštěvovanějších poutních míst v zemi.', 49.0361, 18.6297, 'https://commons.wikimedia.org/wiki/Special:FilePath/Rajecka%20Lesna.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Rajecka%20Lesna.jpg"}'::text[], 1),
    (v_route, 'Fačkovské sedlo a Kľak', 'Horské sedlo (802 m) mezi Lúčanskou Malou Fatrou a pohořím Žiar, nad nímž se zvedá nápadný skalnatý vrchol Kľak. Stoupání z obou stran nabízí rytmické zatáčky a na sedle stojí motorest s parkovištěm – tradiční sraziště motorkářů. Z sedla vede na Kľak dvouhodinová hřebenovka s kruhovým výhledem.', 48.9750, 18.6150, 'https://commons.wikimedia.org/wiki/Special:FilePath/K%C4%BEak%20(vrch).jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/K%C4%BEak%20(vrch).jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Fackovske%20sedlo.jpg"}'::text[], 2),
    (v_route, 'Bojnický zámek', 'Nejnavštěvovanější a nejromantičtější zámek Slovenska, přestavěný koncem 19. století podle francouzských loirských vzorů. Pod věžemi s modrými střechami roste sedmisetletá lípa krále Matyáše a v podzámčí sídlí nejstarší zoo v zemi. Prohlídkové okruhy vedou i do travertinové jeskyně přímo pod hradním nádvořím.', 48.7800, 18.5775, 'https://commons.wikimedia.org/wiki/Special:FilePath/Bojnicky%20zamok.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Bojnicky%20zamok.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Bojnice%20Castle.jpg"}'::text[], 3),
    (v_route, 'Restaurace: Meridiana (Bojnice)', 'Stylová restaurace kousek pod zámkem, dlouhodobě řazená k nejlepším podnikům Horní Nitry. Kuchyně kombinuje slovenskou klasiku s moderním bistro pojetím, chválené jsou steaky, domácí dezerty a víkendové menu. Po prohlídce zámku ideální místo na pořádný oběd před zpáteční cestou přes sedlo.', 48.7794, 18.5836, 'https://commons.wikimedia.org/wiki/Special:FilePath/Bojnice.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Bojnice.jpg"}'::text[], 4),
    (v_route, 'Prievidza – Námestie slobody', 'Centrum Horní Nitry s piaristickým kostelem, morovým sloupem a příjemnou pěší zónou. Město bývalo srdcem hornického regionu – o dobývání uhlí vypráví místní hornická expozice. Praktická zastávka na doplnění paliva i sil před návratem do Rajecké doliny.', 48.7746, 18.6260, 'https://commons.wikimedia.org/wiki/Special:FilePath/Prievidza.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Prievidza.jpg"}'::text[], 5);
  insert into public.routes
    (id, branch_id, name, description, route_type, distance_km, duration_min, difficulty,
  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Hrad Devín', 'Monumentální zřícenina na skále nad soutokem Dunaje a Moravy, jedno z nejvýznamnějších míst slovenské historie od dob Velké Moravy. Z hradeb se díváte přímo do Rakouska – za železné opony tudy vedla ostře střežená hranice, což připomíná Brána svobody pod hradem. Skvělé místo na úvodní fotku celé vinné cesty.', 48.1736, 16.9781, 'https://commons.wikimedia.org/wiki/Special:FilePath/Devin%20Castle.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Devin%20Castle.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Hrad%20Devin.jpg"}'::text[], 0),
    (v_route, 'Svätý Jur', 'Nejstarší vinařské městečko Malých Karpat s památkovou rezervací vinohradnických domů a gotickým kostelem svatého Jiří. Vinice tu obdělávají už od římských dob a místní ryzlinky patří k nejlepším v zemi. Úzkými uličkami projíždějte pomalu – o víkendech tu bývá živo.', 48.2519, 17.2158, 'https://commons.wikimedia.org/wiki/Special:FilePath/Svaty%20Jur.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Svaty%20Jur.jpg"}'::text[], 1),
    (v_route, 'Modra – město vína a keramiky', 'Srdce malokarpatského vinařství a domov proslulé modranské majoliky – ručně malované keramiky s třistaletou tradicí. Ve městě dožil národní buditel Ľudovít Štúr, jehož muzeum stojí na náměstí. Nad městem se z rozhledny na Veľké homoli otevírá výhled na moře vinic.', 48.3339, 17.3061, 'https://commons.wikimedia.org/wiki/Special:FilePath/Modra.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Modra.jpg"}'::text[], 2),
    (v_route, 'Restaurace: Elesko Wine Park (Modra)', 'Moderní vinařský areál mezi vinicemi u Modry s vyhlášenou restaurací, degustačními sklepy a galerií umění. Kuchyně staví na sezonních surovinách a párování s vlastními víny z okolních svahů; hodnocení hostů patří k nejvyšším v regionu. Řidičům ochotně nabídnou nealko variantu degustace.', 48.3489, 17.3183, 'https://commons.wikimedia.org/wiki/Special:FilePath/Modra%20vinohrady.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Modra%20vinohrady.jpg"}'::text[], 3),
    (v_route, 'Hrad Červený Kameň', 'Mohutný renesanční hrad rodu Pálffyů nad obcí Častá s nejrozsáhlejšími hradními sklepy ve střední Evropě – budovali je Fuggerové jako sklad mědi. Interiéry patří k nejzachovalejším v zemi a na nádvoří se konají sokolnické ukázky. Pod hradem je velké parkoviště a stánek s občerstvením.', 48.3936, 17.3336, 'https://commons.wikimedia.org/wiki/Special:FilePath/Hrad%20Cerveny%20Kamen.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Hrad%20Cerveny%20Kamen.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Cerveny%20Kamen%20castle.jpg"}'::text[], 4),
    (v_route, 'Jaskyňa Driny', 'Jediná zpřístupněná jeskyně na západním Slovensku, ukrytá v lesích Malých Karpat nad Smolenicemi. Úzké puklinové chodby zdobí sintrové záclony a vodopády – prohlídka trvá asi 35 minut. Od parkoviště v dolině Hlboča vede k vchodu čtvrthodinová procházka bukovým lesem.', 48.4986, 17.4283, 'https://commons.wikimedia.org/wiki/Special:FilePath/Jaskyna%20Driny.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Jaskyna%20Driny.jpg"}'::text[], 5),
    (v_route, 'Smolenický zámek', 'Pohádkový zámek s kuželovitými věžemi na zalesněném kopci nad Smolenicemi, postavený začátkem 20. století rodem Pálffyů na místě staršího hradu. Dnes slouží jako kongresové centrum akademie věd, park a věž jsou v sezóně přístupné veřejnosti. Silueta nad vinicemi je důstojnou tečkou za vinnou cestou.', 48.5106, 17.4297, 'https://commons.wikimedia.org/wiki/Special:FilePath/Smolenicky%20zamok.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Smolenicky%20zamok.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Smolenice%20Castle.jpg"}'::text[], 6);
  insert into public.routes
    (id, branch_id, name, description, route_type, distance_km, duration_min, difficulty,
  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Skalica – rotunda svatého Jiří', 'Románská rotunda z 12. století na hradním návrší je symbolem svobodného královského města Skalica. Dole na trojúhelníkovém náměstí ochutnáte originální skalický trdelník – první chráněný slovenský produkt – a místní růžové víno, skalický rubín. Historické jádro s farským kostelem a jezuitskou kolejí stojí za procházku.', 48.8447, 17.2270, 'https://commons.wikimedia.org/wiki/Special:FilePath/Skalica%20rotunda.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Skalica%20rotunda.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Skalica.jpg"}'::text[], 0),
    (v_route, 'Holíčský zámek', 'Barokní zámek císaře Františka Štěpána Lotrinského, manžela Marie Terezie, obklopený vodním příkopem a rozlehlým parkem. Habsburská rodina sem jezdila na letní pobyty a v zámku sídlila proslulá manufaktura na fajáns. Areál s příkopy a konírnami je volně přístupný, interiéry v sezóně.', 48.8117, 17.1628, 'https://commons.wikimedia.org/wiki/Special:FilePath/Holicsky%20zamok.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Holicsky%20zamok.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Holic%20zamok.jpg"}'::text[], 1),
    (v_route, 'Větrný mlýn Holíč', 'Jediný zachovalý zděný větrný mlýn holandského typu na Slovensku, stojící na návrší nad Holíčem. Válcová stavba z 19. století sloužila k mletí obilí pro císařské panství a dnes je vyhledávaným vyhlídkovým bodem. Od mlýna přehlédnete rovinu Záhoří až k Bílým Karpatům.', 48.7997, 17.1719, 'https://commons.wikimedia.org/wiki/Special:FilePath/Veterny%20mlyn%20Holic.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Veterny%20mlyn%20Holic.jpg"}'::text[], 2),
    (v_route, 'Bazilika Šaštín-Stráže', 'Národní svatyně Slovenska s milostnou sochou Sedmibolestné Panny Marie, patronky země, kam každoročně putují statisíce poutníků. Monumentální barokní chrám s dvouvěžovým průčelím navrhli stavitelé císařského dvora a vysvěcen byl za účasti Marie Terezie. Poutní areál nabízí i stylové občerstvení.', 48.6383, 17.1489, 'https://commons.wikimedia.org/wiki/Special:FilePath/Sastin%20bazilika.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Sastin%20bazilika.jpg"}'::text[], 3),
    (v_route, 'Plavecký hrad', 'Rozeklaná zřícenina královského pohraničního hradu ze 13. století na vápencovém hřebeni Malých Karpat. Půlhodinový výstup od Plaveckého Podhradí odmění výhledem na celou rovinu Záhoří až k rakouským Alpám při dobré viditelnosti. Okolní skály jsou rájem horolezců a paraglidistů.', 48.4900, 17.2650, 'https://commons.wikimedia.org/wiki/Special:FilePath/Plavecky%20hrad.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Plavecky%20hrad.jpg"}'::text[], 4),
    (v_route, 'Hrad Branč', 'Rozsáhlá zřícenina na travnatém kopci nad Podbrančem, strážící kdysi uherskou hranici proti Moravě. V 17. století sloužil hrad jako vězení protestantských kněží, což připomíná památník na nádvoří. Přístup je volný a z hradeb se otevírá kruhový výhled na myjavské kopanice.', 48.6489, 17.5372, 'https://commons.wikimedia.org/wiki/Special:FilePath/Hrad%20Branc.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Hrad%20Branc.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Branc%20hrad.jpg"}'::text[], 5),
    (v_route, 'Restaurace: Sv. Michal (Skalica)', 'Stylová restaurace a penzion v historickém domě u skalického náměstí, pojmenovaná po patronovi města. Vaří poctivou záhoráckou kuchyni – husacinu s lokšemi, zvěřinu i denní menu – a k tomu nabízejí vína místních vinařů včetně skalického rubínu. Výborně hodnocená tečka za okruhem, trdelník na cestu si zabalte z pekárny za rohem.', 48.8455, 17.2262, 'https://commons.wikimedia.org/wiki/Special:FilePath/Skalica%20namestie.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Skalica%20namestie.jpg"}'::text[], 6);
  insert into public.routes
    (id, branch_id, name, description, route_type, distance_km, duration_min, difficulty,
  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Vodní dílo Gabčíkovo', 'Největší vodní stavba Slovenska s hrází, elektrárnou a plavebními komorami, jimiž se lodě spouštějí o více než šestnáct metrů. Z koruny hráze je působivý výhled na zdrž Hrušov i proplouvající říční soupravy. U areálu je vyhlídková terasa a informační centrum o dunajské plavbě.', 47.8800, 17.5400, 'https://commons.wikimedia.org/wiki/Special:FilePath/Vodne%20dielo%20Gabcikovo.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Vodne%20dielo%20Gabcikovo.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Gabcikovo%20Dam.jpg"}'::text[], 0),
    (v_route, 'Vodní mlýn Kolárovo', 'Věrná replika plovoucího lodního mlýna na mrtvém rameni Malého Dunaje, k níž vede nejdelší krytý dřevěný most v Evropě. Skanzen připomíná doby, kdy na dolním toku klapaly desítky plovoucích mlýnů. Kolem je příjemný lužní háj s moly – ideální stinná zastávka uprostřed roviny.', 47.9250, 18.0080, 'https://commons.wikimedia.org/wiki/Special:FilePath/Vodny%20mlyn%20Kolarovo.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Vodny%20mlyn%20Kolarovo.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Kolarovo%20mlyn.jpg"}'::text[], 1),
    (v_route, 'Pevnost Komárno', 'Největší bastionová pevnost bývalé rakousko-uherské monarchie na soutoku Váhu a Dunaje, která nebyla nikdy dobyta. Systém hradeb, kasemat a bastionů se rozrůstal od tureckých válek až do 19. století a dnes se uchází o zápis do UNESCO. Prohlídky s průvodcem vedou i do rozsáhlého podzemí.', 47.7575, 18.1350, 'https://commons.wikimedia.org/wiki/Special:FilePath/Komarno%20pevnost.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Komarno%20pevnost.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Pevnost%20Komarno.jpg"}'::text[], 2),
    (v_route, 'Nádvoří Evropy (Komárno)', 'Originální náměstí v centru Komárna, kde každý dům reprezentuje architekturu jiné evropské země či regionu. Barevný soubor pětačtyřiceti staveb doplňují sochy uherských panovníků a průchody do historického jádra rodiště Mórа Jókaiho. Vděčné místo na fotku a zmrzlinu.', 47.7597, 18.1289, 'https://commons.wikimedia.org/wiki/Special:FilePath/Nadvorie%20Europy.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Nadvorie%20Europy.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Nadvorie%20Europy%20Komarno.jpg"}'::text[], 3),
    (v_route, 'Restaurace: Banderium (Komárno)', 'Historická restaurace v měšťanském domě u hlavního náměstí Komárna, proslulá poctivou maďarsko-slovenskou kuchyní jihu. Perkelt, halászlé i husí játra tu dělají tak, jak mají – s pořádnou porcí papriky; hodnocení hostů patří k nejlepším ve městě. Zastávka na oběd před závěrečnou rovinkou do Štúrova.', 47.7586, 18.1275, 'https://commons.wikimedia.org/wiki/Special:FilePath/Komarno%20namestie.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Komarno%20namestie.jpg"}'::text[], 4),
    (v_route, 'Most Márie Valérie (Štúrovo)', 'Ocelový most přes Dunaj spojující Štúrovo s maďarskou Ostřihomí, pojmenovaný po dceři císaře Františka Josefa I. Půl století ležel po válce v troskách a obnoven byl až roku 2001 jako symbol znovusblížení obou břehů. Z nábřeží ve Štúrově je nejkrásnější výhled na mohutnou ostřihomskou baziliku – důstojná závěrečná fotka trasy.', 47.7942, 18.7189, 'https://commons.wikimedia.org/wiki/Special:FilePath/Most%20Marie%20Valerie.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Most%20Marie%20Valerie.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Maria%20Valeria%20Bridge.jpg"}'::text[], 5);
