-- ════════════════════════════════════════════════════════════════════
-- MotoGo24 — SEED doporučených tras — SLOVENSKO II (10 tras, sort 5310–5400)
-- NEAPLIKOVÁNO na živou DB — přehled a spuštění je na adminovi.
-- Trasy: is_active=false (Skryto) + status='approved' → ve Velíně zkontroluj a Publikuj.
-- Idempotence: každá trasa se před vložením smaže dle (name, branch_id).
-- ════════════════════════════════════════════════════════════════════
alter table public.routes add column if not exists countries text[] not null default '{}'::text[];

do $$
declare
  v_branch uuid;
  v_route  uuid;
begin
  -- Domovská pobočka = nejbližší k Mezné (49.3464, 15.2119); fallback první.
  select id into v_branch from public.branches
    order by (power(coalesce(gps_lat,0)-49.3464,2) + power(coalesce(gps_lng,0)-15.2119,2)) asc
    limit 1;
  if v_branch is null then
    raise exception 'Nenalezena žádná pobočka v public.branches — nelze nasadit trasy.';
  end if;

  -- Pieniny a Zamagurie – plte na Dunajci
  delete from public.routes where name = 'Pieniny a Zamagurie – plte na Dunajci' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Pieniny a Zamagurie – plte na Dunajci', 'Okruh nejsevernějším koutem Spiše vás zavede do kraje goralských roubenek, dřevěných kostelíků a divoké řeky Dunajec. Z Kežmarku stoupáte přes malebný Ždiar pod Belianskými Tatrami a po úzké silničce do Osturni, památkové rezervace lidové architektury táhnoucí se sedm kilometrů podél potoka. Následuje sjezd k Červenému Kláštoru, odkud vyplouvají tradiční vory – plte – do vápencového Prielomu Dunajca pod Tromi korunami. Zpáteční cesta vede podél polské hranice k mohutnému hradu Stará Ľubovňa a zvlněným Zamagurím zpět do Kežmarku. Nejlepší období je květen až září; počítejte s úzkými, místy záplatovanými silničkami, pomalými traktory a o víkendech s pěší turistikou kolem přístavišť plťařů.', 'loop', 130, 210, 'medium',
     '[{"lat": 49.1366, "lng": 20.4292, "label": "Start: Kežmarok"}, {"lat": 49.2717, "lng": 20.2661, "label": "Ždiar"}, {"lat": 49.3369, "lng": 20.2264, "label": "Osturňa"}, {"lat": 49.3946, "lng": 20.4224, "label": "Červený Kláštor"}, {"lat": 49.3025, "lng": 20.6903, "label": "Stará Ľubovňa"}, {"lat": 49.1366, "lng": 20.4292, "label": "Cíl: Kežmarok"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=49.1366,20.4292&destination=49.1366,20.4292&travelmode=driving&waypoints=49.2717,20.2661%7C49.3369,20.2264%7C49.3946,20.4224%7C49.3025,20.6903', 'https://commons.wikimedia.org/wiki/Special:FilePath/Kezmarok%20Castle.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Kezmarok%20Castle.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Zdiar.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Osturna.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/%C4%8Cerven%C3%BD%20Kl%C3%A1%C5%A1tor.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Prielom%20Dunajca.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Lubovniansky%20hrad.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Kezmarok.jpg"}'::text[], '{"Kežmarský hrad","Ždiar","Osturňa","Červený Kláštor","Prielom Dunajca – plte","Hrad Stará Ľubovňa","Restaurace: Hotel Hviezdoslav (Kežmarok)"}'::text[], '{"SK"}'::text[], false, 5310, 'approved');

  -- Šariš – Bardejov a dřevěné kostelíky
  delete from public.routes where name = 'Šariš – Bardejov a dřevěné kostelíky' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Šariš – Bardejov a dřevěné kostelíky', 'Pohodový okruh krajem Šariše spojuje dvě historická města a to nejlepší z lidové sakrální architektury východního Slovenska. Z Prešova vyjedete údolím Torysy kolem zříceniny Šarišského hradu a zvlněnou pahorkatinou pokračujete do středověkého Bardejova, jehož náměstí s gotickou radnicí chrání UNESCO. Kousek za městem se schovávají lázně Bardejovské kúpele s kolonádou a skanzenem a na zpáteční cestě dřevěný kostelík v Hervartově – nejstarší a nejzachovalejší na Slovensku. Silnice jsou tu široké a klidné, ideální na uvolněnou jízdu s výhledy na Čergov. Trasa je sjízdná od jara do podzimu; pozor jen na zvěř v lesních úsecích a na letní bouřky, které se od Beskyd přiženou rychle.', 'loop', 145, 220, 'easy',
     '[{"lat": 48.9986, "lng": 21.2394, "label": "Start: Prešov"}, {"lat": 49.0378, "lng": 21.1928, "label": "Veľký Šariš"}, {"lat": 49.2937, "lng": 21.2765, "label": "Bardejov"}, {"lat": 49.3220, "lng": 21.2650, "label": "Bardejovské kúpele"}, {"lat": 49.2453, "lng": 21.2166, "label": "Hervartov"}, {"lat": 48.9986, "lng": 21.2394, "label": "Cíl: Prešov"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=48.9986,21.2394&destination=48.9986,21.2394&travelmode=driving&waypoints=49.0378,21.1928%7C49.2937,21.2765%7C49.3220,21.2650%7C49.2453,21.2166', 'https://commons.wikimedia.org/wiki/Special:FilePath/Bardejov%20-%20Radni%C4%8Dn%C3%A9%20n%C3%A1mestie.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Pre%C5%A1ov%20-%20Hlavn%C3%A1%20ulica.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Sarissky%20hrad.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Bardejov%20-%20Radni%C4%8Dn%C3%A9%20n%C3%A1mestie.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Bardejovske%20kupele.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Hervartov%20church.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Bardejov%20radnica.jpg"}'::text[], '{"Prešov – Hlavná ulica","Šarišský hrad","Bardejov – Radničné námestie (UNESCO)","Bardejovské kúpele","Dřevěný kostelík Hervartov (UNESCO)","Restaurace: Roland (Bardejov)"}'::text[], '{"SK"}'::text[], false, 5320, 'approved');

  -- Poloniny a Vihorlat – nejvýchodnější Slovensko
  delete from public.routes where name = 'Poloniny a Vihorlat – nejvýchodnější Slovensko' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Poloniny a Vihorlat – nejvýchodnější Slovensko', 'Výprava na úplný východní konec Slovenska, do nejřidčeji osídleného kouta země, kde se potkávají hranice tří států. Z Humenného sjedete k rekreačnímu moři východu – Zemplínské šíravě – a lesní silničkou vystoupáte k jezeru Morské oko pod sopečným Vihorlatem. Přes Sninu pak pokračujete do Parku tmavé oblohy Poloniny kolem hvězdárny na Kolonickém sedle a rusínskými vesničkami s dřevěnými kostelíky až do Nové Sedlice, nejvýchodnější obce republiky. Silnice jsou úzké, zvlněné a téměř prázdné – jízda tu má meditativní tempo. Nejlépe od června do října; počítejte s horším povrchem v zapadlých údolích, zvěří na silnici a minimem čerpacích stanic – tankujte ve Snině.', 'poi', 140, 240, 'medium',
     '[{"lat": 48.9317, "lng": 21.9067, "label": "Start: Humenné"}, {"lat": 48.7942, "lng": 22.0500, "label": "Zemplínska šírava"}, {"lat": 48.9126, "lng": 22.2833, "label": "Morské oko"}, {"lat": 48.9878, "lng": 22.1517, "label": "Snina"}, {"lat": 48.9353, "lng": 22.2764, "label": "Kolonické sedlo"}, {"lat": 49.0322, "lng": 22.3378, "label": "Topoľa"}, {"lat": 49.0511, "lng": 22.5153, "label": "Cíl: Nová Sedlica"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=48.9317,21.9067&destination=49.0511,22.5153&travelmode=driving&waypoints=48.7942,22.0500%7C48.9126,22.2833%7C48.9878,22.1517%7C48.9353,22.2764%7C49.0322,22.3378', 'https://commons.wikimedia.org/wiki/Special:FilePath/Morske%20oko.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Kastiel%20Humenne.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Zemplinska%20sirava.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Morske%20oko.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Kastiel%20Snina.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Kolonica%20Observatory.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Topo%C4%BEa%20-%20dreven%C3%BD%20kostol%C3%ADk.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Nova%20Sedlica.jpg"}'::text[], '{"Kaštieľ Humenné","Zemplínska šírava","Morské oko (Vihorlat)","Restaurace: Kaštieľ Snina (Snina)","Hvezdáreň Kolonica – Park tmavé oblohy","Dřevěný kostelík Topoľa","Nová Sedlica – nejvýchodnější obec"}'::text[], '{"SK"}'::text[], false, 5330, 'approved');

  -- Zemplín a slovenský Tokaj
  delete from public.routes where name = 'Zemplín a slovenský Tokaj' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Zemplín a slovenský Tokaj', 'Vinařský okruh nejjižnějším Zemplínem začíná u jediného gejzíru střední Evropy v Herľanech a pokračuje pod zříceninu hradu Slanec, střežící průsmyk mezi Košickou kotlinou a Zemplínem. Pak už se před vámi otevřou slunečné vinice slovenské části světoznámé tokajské oblasti – rozhledna ve tvaru vinného soudku nad Veľkou Tŕňou, stovky let staré tufové sklepy v Malé Tŕni a renesanční kaštieľ v Borši, rodiště Františka II. Rákócziho. Zpět do Košic se vracíte rovinatým Zemplínem kolem kaštieľu v Trebišově. Silnice jsou klidné a přehledné, trasa je ideální na jaře a na podzim v době vinobraní. Ochutnávku vína si nechte až na večer po odstavení motorky – degustace tu berou vážně.', 'loop', 190, 270, 'easy',
     '[{"lat": 48.7164, "lng": 21.2611, "label": "Start: Košice"}, {"lat": 48.8014, "lng": 21.4767, "label": "Herľany"}, {"lat": 48.6353, "lng": 21.4750, "label": "Slanec"}, {"lat": 48.4550, "lng": 21.6850, "label": "Veľká Tŕňa"}, {"lat": 48.3944, "lng": 21.7161, "label": "Borša"}, {"lat": 48.6280, "lng": 21.7190, "label": "Trebišov"}, {"lat": 48.7164, "lng": 21.2611, "label": "Cíl: Košice"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=48.7164,21.2611&destination=48.7164,21.2611&travelmode=driving&waypoints=48.8014,21.4767%7C48.6353,21.4750%7C48.4550,21.6850%7C48.3944,21.7161%7C48.6280,21.7190', 'https://commons.wikimedia.org/wiki/Special:FilePath/Herliansky%20gejzir.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Herliansky%20gejzir.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Slanec%20hrad.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Rozh%C4%BEad%C5%88a%20Tokaj.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Mala%20Trna.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Kastiel%20Borsa.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Kastiel%20Trebisov.jpg"}'::text[], '{"Herliansky gejzír","Hrad Slanec","Rozhledna Tokaj (Veľká Tŕňa)","Restaurace: Tokaj Macík Winery (Malá Tŕňa)","Kaštieľ Borša","Kaštieľ Andrássyovců (Trebišov)"}'::text[], '{"SK"}'::text[], false, 5340, 'approved');

  -- Gemer a Muránska planina
  delete from public.routes where name = 'Gemer a Muránska planina' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Gemer a Muránska planina', 'Trasa zapomenutým Gemerem spojuje unikátní podzemí, hradní romantiku a jednu z nejhezčích horských silnic středního Slovenska. Z Rožňavy zamíříte přes Štítnik k Ochtinské aragonitové jeskyni, světové raritě zapsané v UNESCO, a dál gemerskými městečky do Revúce, kolébky slovenského školství. Následuje stoupání pod majestátní zříceninu Muránského hradu a přejezd Muránské planiny přes sedlo Zbojská s vyhlášeným salašem – serpentiny mezi Muráněm a Tisovcem patří k nejoblíbenějším motorkářským úsekům v zemi. Provoz je tu minimální, krajina divoká; dávejte pozor na zvěř, lesní techniku a v zatáčkách na zbytky štěrku. Nejlepší období je květen až říjen.', 'poi', 100, 180, 'medium',
     '[{"lat": 48.6603, "lng": 20.5342, "label": "Start: Rožňava"}, {"lat": 48.6614, "lng": 20.3739, "label": "Štítnik"}, {"lat": 48.6656, "lng": 20.3011, "label": "Ochtinská aragonitová jaskyňa"}, {"lat": 48.6831, "lng": 20.1153, "label": "Revúca"}, {"lat": 48.7469, "lng": 20.0392, "label": "Muráň"}, {"lat": 48.7228, "lng": 19.8983, "label": "Sedlo Zbojská"}, {"lat": 48.6800, "lng": 19.9436, "label": "Cíl: Tisovec"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=48.6603,20.5342&destination=48.6800,19.9436&travelmode=driving&waypoints=48.6614,20.3739%7C48.6656,20.3011%7C48.6831,20.1153%7C48.7469,20.0392%7C48.7228,19.8983', 'https://commons.wikimedia.org/wiki/Special:FilePath/Ochtinska%20aragonitova%20jaskyna.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Ochtinska%20aragonitova%20jaskyna.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Prve%20slovenske%20gymnazium%20Revuca.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Muransky%20hrad.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Muranska%20planina.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Sedlo%20Zbojska.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Tisovec.jpg"}'::text[], '{"Ochtinská aragonitová jaskyňa (UNESCO)","Revúca – První slovenské gymnázium","Muránský hrad","Muránska planina – Veľká lúka","Restaurace: Salaš Zbojská (sedlo Zbojská)","Tisovec – ozubnicová dráha"}'::text[], '{"SK"}'::text[], false, 5350, 'approved');

  -- Turiec a Veľká Fatra – přes zlatou Kremnici
  delete from public.routes where name = 'Turiec a Veľká Fatra – přes zlatou Kremnici' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Turiec a Veľká Fatra – přes zlatou Kremnici', 'Okruh Turčianskou kotlinou a horami kolem ní nabízí největší koncentraci serpentin na středním Slovensku. Z Martina projedete pod vápencovými srázy Veľké Fatry k Blatnici a ústí skalní Gaderské doliny, pak vás čeká legendární stoupání přes Harmanec – nejklikatější silniční úsek v zemi s desítkami vracečkových zatáček v bukovém lese a zastávkou u Harmanecké jeskyně. Přes Kremnické Bane, geografický střed Evropy, sjedete do zlatohorní Kremnice s nejstarší dosud fungující mincovnou na světě a údolím Turce se vrátíte přes lázně Turčianske Teplice zpět. Trasa je nejhezčí od května do října; na harmaneckých serpentinách počítejte s kamiony, vlhkem ve stínu lesa a dvojitou plnou čárou – předjíždějte s rozumem.', 'loop', 150, 240, 'medium',
     '[{"lat": 49.0664, "lng": 18.9217, "label": "Start: Martin"}, {"lat": 48.9367, "lng": 18.9339, "label": "Blatnica"}, {"lat": 48.8147, "lng": 19.0403, "label": "Harmanec"}, {"lat": 48.7400, "lng": 18.9130, "label": "Kremnické Bane"}, {"lat": 48.7050, "lng": 18.9183, "label": "Kremnica"}, {"lat": 48.8631, "lng": 18.8611, "label": "Turčianske Teplice"}, {"lat": 49.0664, "lng": 18.9217, "label": "Cíl: Martin"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=49.0664,18.9217&destination=49.0664,18.9217&travelmode=driving&waypoints=48.9367,18.9339%7C48.8147,19.0403%7C48.7400,18.9130%7C48.7050,18.9183%7C48.8631,18.8611', 'https://commons.wikimedia.org/wiki/Special:FilePath/Kremnica.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/M%C3%BAzeum%20slovenskej%20dediny.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Gaderska%20dolina.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Harmanecka%20jaskyna.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Kremnicke%20Bane.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Kremnica.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Turcianske%20Teplice.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Martin%20(Slovakia).jpg"}'::text[], '{"Múzeum slovenskej dediny (Martin)","Gaderská dolina (Blatnica)","Harmanecká jaskyňa","Kremnické Bane – střed Evropy","Kremnica – mincovna a městský hrad","Turčianske Teplice","Restaurace: Hotel Čierna pani (Martin)"}'::text[], '{"SK"}'::text[], false, 5360, 'approved');

  -- Rajecká dolina a zámek Bojnice
  delete from public.routes where name = 'Rajecká dolina a zámek Bojnice' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Rajecká dolina a zámek Bojnice', 'Okruh spojující malebnou Rajeckou dolinu s hornonitranskou kotlinou a nejromantičtějším zámkem Slovenska. Od lázní v Rajeckých Teplicích stoupáte dolinou k poutní bazilice v Rajecké Lesné s vyřezávaným pohyblivým Slovenským betlémem a dál na Fačkovské sedlo pod skalnatým Kľakem – stoupání i sjezd nabízejí výborný rytmus zatáček. Na Horní Nitře vás čeká pohádkový Bojnický zámek s nejstarší lípou v zemi a náměstí v Prievidzi, zpět se vracíte přes Nitrianske Pravno a znovu přes sedlo, tentokrát z druhé strany. Silnice první třídy přes Fačkov má kvalitní povrch, ale o víkendech i hustší provoz; brzy ráno si serpentiny užijete nejvíc. Ideální od dubna do října.', 'loop', 165, 250, 'medium',
     '[{"lat": 49.1264, "lng": 18.6828, "label": "Start: Rajecké Teplice"}, {"lat": 49.0361, "lng": 18.6297, "label": "Rajecká Lesná"}, {"lat": 48.9750, "lng": 18.6150, "label": "Fačkovské sedlo"}, {"lat": 48.7746, "lng": 18.6260, "label": "Prievidza"}, {"lat": 48.7800, "lng": 18.5775, "label": "Bojnice"}, {"lat": 48.9089, "lng": 18.6353, "label": "Nitrianske Pravno"}, {"lat": 49.1264, "lng": 18.6828, "label": "Cíl: Rajecké Teplice"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=49.1264,18.6828&destination=49.1264,18.6828&travelmode=driving&waypoints=49.0361,18.6297%7C48.9750,18.6150%7C48.7746,18.6260%7C48.7800,18.5775%7C48.9089,18.6353', 'https://commons.wikimedia.org/wiki/Special:FilePath/Bojnicky%20zamok.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Rajecke%20Teplice.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Rajecka%20Lesna.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/K%C4%BEak%20(vrch).jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Bojnicky%20zamok.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Bojnice.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Prievidza.jpg"}'::text[], '{"Rajecké Teplice – lázně","Rajecká Lesná – Slovenský betlém","Fačkovské sedlo a Kľak","Bojnický zámek","Restaurace: Meridiana (Bojnice)","Prievidza – Námestie slobody"}'::text[], '{"SK"}'::text[], false, 5370, 'approved');

  -- Malokarpatská vinná cesta
  delete from public.routes where name = 'Malokarpatská vinná cesta' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Malokarpatská vinná cesta', 'Nejznámější vinařská cesta Slovenska vede úpatím Malých Karpat od soutoku Dunaje s Moravou až pod Smolenický zámek. Začíná se pod majestátní zříceninou Devína, pokračuje přes vinařská městečka Svätý Jur, Pezinok a Modru, kde se rodí věhlasná frankovka i modranská majolika, a stoupá k mohutnému hradu Červený Kameň s nejzachovalejšími renesančními sklepy ve střední Evropě. Závěr patří lesům nad Smolenicemi – krápníkové jeskyni Driny a pohádkovému zámku na kopci. Silničky mezi vinicemi jsou úzké a zvlněné, s výhledy na Záhorí i Podunajskou nížinu. Trasa je krásná po celou sezónu, vrcholí ale v září při vinobraní; tehdy počítejte se zvýšeným provozem i policejními kontrolami – burčák si nechte zabalit s sebou.', 'poi', 90, 160, 'easy',
     '[{"lat": 48.1736, "lng": 16.9781, "label": "Start: Bratislava-Devín"}, {"lat": 48.2519, "lng": 17.2158, "label": "Svätý Jur"}, {"lat": 48.3339, "lng": 17.3061, "label": "Modra"}, {"lat": 48.3936, "lng": 17.3336, "label": "Červený Kameň"}, {"lat": 48.5117, "lng": 17.4308, "label": "Cíl: Smolenice"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=48.1736,16.9781&destination=48.5117,17.4308&travelmode=driving&waypoints=48.2519,17.2158%7C48.3339,17.3061%7C48.3936,17.3336', 'https://commons.wikimedia.org/wiki/Special:FilePath/Devin%20Castle.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Devin%20Castle.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Svaty%20Jur.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Modra.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Hrad%20Cerveny%20Kamen.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Jaskyna%20Driny.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Smolenicky%20zamok.jpg"}'::text[], '{"Hrad Devín","Svätý Jur","Modra – město vína a keramiky","Restaurace: Elesko Wine Park (Modra)","Hrad Červený Kameň","Jaskyňa Driny","Smolenický zámek"}'::text[], '{"SK"}'::text[], false, 5380, 'approved');

  -- Záhorie – Skalica, Holíč a Plavecký hrad
  delete from public.routes where name = 'Záhorie – Skalica, Holíč a Plavecký hrad' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Záhorie – Skalica, Holíč a Plavecký hrad', 'Pohodový okruh nejzápadnějším koutem Slovenska, krajem borových lesů, vinohradů a habánské historie. Ze Skalice s románskou rotundou a pravým trdelníkem vede trasa do barokního Holíče s císařským zámkem Františka Lotrinského a vzácným větrným mlýnem, pak borovicovými lesy Záhoří k národní bazilice v Šaštíně. Podél západního úpatí Malých Karpat dojedete pod zříceninu Plaveckého hradu na vápencovém hřebeni a přes kopanice se vrátíte kolem hradu Branč zpět. Silnice jsou rovné a rychlé, v lesních úsecích písčité krajnice – ideální nenáročná jarní či podzimní vyjížďka. Pozor na cyklisty na vinohradnických silničkách a na přeběhající zvěř v borech.', 'loop', 150, 220, 'easy',
     '[{"lat": 48.8461, "lng": 17.2264, "label": "Start: Skalica"}, {"lat": 48.8117, "lng": 17.1628, "label": "Holíč"}, {"lat": 48.6383, "lng": 17.1489, "label": "Šaštín-Stráže"}, {"lat": 48.4900, "lng": 17.2650, "label": "Plavecké Podhradie"}, {"lat": 48.6489, "lng": 17.5372, "label": "Podbranč"}, {"lat": 48.6803, "lng": 17.3667, "label": "Senica"}, {"lat": 48.8461, "lng": 17.2264, "label": "Cíl: Skalica"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=48.8461,17.2264&destination=48.8461,17.2264&travelmode=driving&waypoints=48.8117,17.1628%7C48.6383,17.1489%7C48.4900,17.2650%7C48.6489,17.5372%7C48.6803,17.3667', 'https://commons.wikimedia.org/wiki/Special:FilePath/Skalica%20rotunda.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Skalica%20rotunda.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Holicsky%20zamok.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Veterny%20mlyn%20Holic.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Sastin%20bazilika.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Plavecky%20hrad.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Hrad%20Branc.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Skalica%20namestie.jpg"}'::text[], '{"Skalica – rotunda svatého Jiří","Holíčský zámek","Větrný mlýn Holíč","Bazilika Šaštín-Stráže","Plavecký hrad","Hrad Branč","Restaurace: Sv. Michal (Skalica)"}'::text[], '{"SK"}'::text[], false, 5390, 'approved');

  -- Podunají – Žitný ostrov, Komárno a Štúrovo
  delete from public.routes where name = 'Podunají – Žitný ostrov, Komárno a Štúrovo' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Podunají – Žitný ostrov, Komárno a Štúrovo', 'Rovinatá jižní trasa podél Dunaje ukazuje úplně jinou tvář Slovenska – nekonečné lány největšího říčního ostrova Evropy, vodní kanály, pevnosti a maďarský temperament jihu. Z Bratislavy vede přes Žitný ostrov k monumentálnímu vodnímu dílu Gabčíkovo, kde můžete z hráze sledovat proplouvající lodě v obřích plavebních komorách, a dál k pohádkovému plovoucímu mlýnu v Kolárově. V Komárně vás čeká největší pevnostní systém bývalé monarchie a barevné Nádvoří Evropy, finále obstará jízda podél Dunaje do Štúrova s výhledem na ostřihomskou baziliku přes most Márie Valérie. Silnice jsou rovné a rychlé, ideální pro pohodové tempo i cestovní enduro s plnými kufry. Trasa je sjízdná prakticky celoročně; v létě počítejte s horkem nad rozpálenou rovinou – jezděte raději dopoledne.', 'poi', 170, 230, 'easy',
     '[{"lat": 48.1447, "lng": 17.1070, "label": "Start: Bratislava"}, {"lat": 47.8800, "lng": 17.5400, "label": "Gabčíkovo"}, {"lat": 47.9214, "lng": 18.0003, "label": "Kolárovo"}, {"lat": 47.7575, "lng": 18.1350, "label": "Komárno"}, {"lat": 47.7942, "lng": 18.7189, "label": "Cíl: Štúrovo"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=48.1447,17.1070&destination=47.7942,18.7189&travelmode=driving&waypoints=47.8800,17.5400%7C47.9214,18.0003%7C47.7575,18.1350', 'https://commons.wikimedia.org/wiki/Special:FilePath/Vodne%20dielo%20Gabcikovo.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Vodne%20dielo%20Gabcikovo.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Vodny%20mlyn%20Kolarovo.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Komarno%20pevnost.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Nadvorie%20Europy.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Komarno%20namestie.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Most%20Marie%20Valerie.jpg"}'::text[], '{"Vodní dílo Gabčíkovo","Vodní mlýn Kolárovo","Pevnost Komárno","Nádvoří Evropy (Komárno)","Restaurace: Banderium (Komárno)","Most Márie Valérie (Štúrovo)"}'::text[], '{"SK"}'::text[], false, 5400, 'approved');

end $$;
